INSERT INTO message_templates(channel,name,subject,body,management_type,purpose) VALUES
('email','Verificación del negocio · Email','Consulta sobre {{name}}','<p>{{saludo}}</p><p>{{presentacion}}</p><p>Quería confirmar un dato: ¿este es el contacto de {{name}}{{#if city}} en {{city}}{{/if}}?</p><p>Estamos actualizando la información de los negocios turísticos de la zona y queremos que los datos estén al día.</p><p>{{despedida}}</p>',NULL,'verification'),
('whatsapp','Verificación del negocio · WhatsApp',NULL,'<p>{{saludo}} {{presentacion}}</p><p>¿Este es el contacto de {{name}}{{#if city}} en {{city}}{{/if}}?</p><p>Estamos actualizando los datos de los negocios turísticos de la zona. ¡Gracias!</p>',NULL,'verification'),
('social','Verificación del negocio · Instagram',NULL,'<p>{{saludo}} {{presentacion}}</p><p>¿Este es el contacto de {{name}}{{#if city}} en {{city}}{{/if}}?</p><p>Estamos actualizando los datos de los negocios turísticos de la zona. ¡Gracias!</p>',NULL,'verification'),
('email','Primer contacto · Verticales principales · Email','Sumar {{name}} a Hospeda','<p>{{saludo}}</p><p>{{presentacion}}</p><p>Me comunico por {{name}}.{{#if city}} Queremos que quien planea una visita encuentre en un solo lugar dónde dormir, dónde comer y qué hacer {{ref_ciudad}}.{{/if}}</p><p>{{etapa_hospeda}}</p><p>{{propuesta_valor}}</p><p><strong>Para probarlo:</strong> {{prueba_gratis}}</p><p><strong>Nos ocupamos de la carga:</strong> {{ayuda_ficha}}</p><p>{{#if temporada}}{{temporada}}{{/if}}</p><p>Toda la información está acá: <a href="{{link_presentacion}}">{{link_presentacion}}</a></p><p>{{pregunta_presentacion}}</p><p>{{despedida}}</p>','main','first_contact'),
('whatsapp','Primer contacto · Verticales principales · WhatsApp',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Me comunico por {{name}}. {{etapa_corta}}</p><p>{{propuesta_corta}}</p><p><strong>{{prueba_corta}}</strong></p><p>{{pregunta_presentacion}}</p>','main','first_contact'),
('social','Primer contacto · Verticales principales · Instagram',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Me comunico por {{name}}. {{etapa_corta}}</p><p>{{propuesta_corta}}</p><p><strong>{{prueba_corta}}</strong></p><p>{{pregunta_presentacion}}</p>','main','first_contact'),
('email','Primer contacto · Aliados · Email','Programa de aliados de Hospeda','<p>{{saludo}}</p><p>{{presentacion}}</p><p>Me comunico por {{name}}. {{propuesta_aliados}}</p><p>El programa incluye:</p><ul><li>Logo en la portada de Hospeda</li><li>Difusión en nuestras redes y en el newsletter</li><li>Registro de cada aparición</li></ul><p>{{etapa_hospeda}}</p><p>El nivel y los valores se definen en una charla, según cada caso. Más información: <a href="{{link_aliados}}">{{link_aliados}}</a></p><p>{{pregunta_presentacion}}</p><p>{{despedida}}</p>','partner','first_contact'),
('whatsapp','Primer contacto · Aliados · WhatsApp',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Me comunico por {{name}}. {{propuesta_aliados}}</p><p>Incluye logo en la portada y difusión en redes y newsletter.</p><p>{{pregunta_presentacion}}</p>','partner','first_contact'),
('social','Primer contacto · Aliados · Instagram',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Me comunico por {{name}}. {{propuesta_aliados}}</p><p>Incluye logo en la portada y difusión en redes y newsletter.</p><p>{{pregunta_presentacion}}</p>','partner','first_contact'),
('email','Primer contacto · Proveedores · Email','Directorio de proveedores de Hospeda','<p>{{saludo}}</p><p>{{presentacion}}</p><p>Me comunico por {{name}}. {{propuesta_proveedores}}</p><ul><li>Publicar es gratis y no hay comisiones.</li><li>Los anfitriones contactan directo por WhatsApp.</li><li>A cambio, cada proveedor ofrece un beneficio propio a los anfitriones.</li></ul><p>Así funciona: <a href="{{link_proveedores}}">{{link_proveedores}}</a></p><p>{{pregunta_presentacion}}</p><p>{{despedida}}</p>','provider','first_contact'),
('whatsapp','Primer contacto · Proveedores · WhatsApp',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Me comunico por {{name}}. {{propuesta_proveedores}}</p><p>Publicar es gratis y el contacto es directo.</p><p>{{pregunta_presentacion}}</p>','provider','first_contact'),
('social','Primer contacto · Proveedores · Instagram',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Me comunico por {{name}}. {{propuesta_proveedores}}</p><p>Publicar es gratis y el contacto es directo.</p><p>{{pregunta_presentacion}}</p>','provider','first_contact'),
('email','Primer contacto · Editores · Email','Colaboración editorial con Hospeda','<p>{{saludo}}</p><p>{{presentacion}}</p><p>{{propuesta_editores}}</p><ul><li>Es una colaboración voluntaria y sin exclusividad.</li><li>Cada editor tiene su página de autor.</li><li>Difundimos lo publicado en nuestras redes.</li><li>El texto sigue siendo de quien lo escribe.</li></ul><p>Más detalles: <a href="{{link_editores}}">{{link_editores}}</a></p><p>{{pregunta_presentacion}}</p><p>{{despedida}}</p>','editor','first_contact'),
('whatsapp','Primer contacto · Editores · WhatsApp',NULL,'<p>{{saludo}} {{presentacion}}</p><p>{{propuesta_editores}}</p><p>Es voluntario y sin exclusividad.</p><p>{{pregunta_presentacion}}</p>','editor','first_contact'),
('social','Primer contacto · Editores · Instagram',NULL,'<p>{{saludo}} {{presentacion}}</p><p>{{propuesta_editores}}</p><p>Es voluntario y sin exclusividad.</p><p>{{pregunta_presentacion}}</p>','editor','first_contact'),
('email','Retomar conversación · Email','Retomando lo de {{name}} y Hospeda','<p>{{saludo}}</p><p>{{presentacion}}</p><p>Retomo lo que hablamos sobre {{name}} y Hospeda.</p><p>{{#if temporada}}{{temporada}}{{/if}}</p><p>Dejo de nuevo la información: <a href="{{link_presentacion}}">{{link_presentacion}}</a></p><p>{{pregunta_retomar}}</p><p>{{despedida}}</p>',NULL,'resume'),
('whatsapp','Retomar conversación · WhatsApp',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Retomo lo que hablamos sobre {{name}}.</p><p>{{pregunta_retomar}}</p>',NULL,'resume'),
('social','Retomar conversación · Instagram',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Retomo lo que hablamos sobre {{name}}.</p><p>{{pregunta_retomar}}</p>',NULL,'resume'),
('email','Relación y novedades · Email','Novedades de Hospeda','<p>{{saludo}}</p><p>{{presentacion}}</p><p>Comparto novedades de Hospeda: seguimos sumando alojamientos, gastronomía y experiencias de la región.</p><p>La idea es que quien viaja encuentre todo en un solo lugar.</p><p>Lo nuevo se publica en <a href="{{link_hospeda}}">{{link_hospeda}}</a> y en Instagram: <a href="{{link_instagram}}">{{link_instagram}}</a></p><p>{{despedida}}</p>',NULL,'relationship'),
('whatsapp','Relación y novedades · WhatsApp',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Seguimos sumando alojamientos, gastronomía y experiencias de la región.</p><p>Lo nuevo lo publicamos en Instagram: {{link_instagram}}</p><p>{{despedida}}</p>',NULL,'relationship'),
('social','Relación y novedades · Instagram',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Seguimos sumando alojamientos, gastronomía y experiencias de la región.</p><p>Lo nuevo lo publicamos en Instagram: {{link_instagram}}</p><p>{{despedida}}</p>',NULL,'relationship'),
('email','Acompañamiento · Bienvenida · Email','Bienvenida a Hospeda · {{name}}','<p>{{saludo}}</p><p>{{presentacion}}</p><p>Gracias por sumar {{name}} a Hospeda.</p><p>Para armar la ficha necesitamos:</p><ul><li>Fotos (la principal y algunas más)</li><li>Una descripción breve</li><li>Horarios y datos de contacto</li><li>Redes o sitio web, si los hay</li></ul><p>Así sigue:</p><ol><li>Se crea la cuenta en Hospeda.</li><li>Armamos la ficha con ese material.</li><li>Al publicarla empiezan los 30 días de prueba.</li><li>Antes de que terminen, ayudamos a elegir el plan.</li></ol><p>Cualquier consulta, estamos en el {{telefono_hospeda}}.</p><p>{{despedida}}</p>','accompaniment','care'),
('whatsapp','Acompañamiento · Bienvenida · WhatsApp',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Gracias por sumar {{name}} a Hospeda.</p><p>Para armar la ficha necesitamos fotos, una descripción breve, horarios y datos de contacto.</p><p>Al publicarla empiezan los 30 días de prueba.</p><p>{{despedida}}</p>','accompaniment','care'),
('social','Acompañamiento · Bienvenida · Instagram',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Gracias por sumar {{name}} a Hospeda.</p><p>Para armar la ficha necesitamos fotos, una descripción breve, horarios y datos de contacto.</p><p>Al publicarla empiezan los 30 días de prueba.</p><p>{{despedida}}</p>','accompaniment','care'),
('email','Acompañamiento · Fin de la prueba · Email','La prueba de {{name}} en Hospeda está por terminar','<p>{{saludo}}</p><p>{{presentacion}}</p><p>La prueba de 30 días de {{name}} en Hospeda está por terminar.</p><p>Para que la ficha siga visible, hay que elegir un plan desde la cuenta.</p><p>Si no se elige ninguno, la ficha deja de verse, pero no se borra: vuelve a publicarse al elegir un plan.</p><p>Si hace falta, ayudamos a elegir el plan que mejor se ajuste. Planes y detalles: <a href="{{link_presentacion}}">{{link_presentacion}}</a></p><p>{{despedida}}</p>','accompaniment','care'),
('whatsapp','Acompañamiento · Fin de la prueba · WhatsApp',NULL,'<p>{{saludo}} {{presentacion}}</p><p>La prueba de 30 días de {{name}} en Hospeda está por terminar.</p><p>Para que la ficha siga visible hay que elegir un plan desde la cuenta. Si hace falta, ayudamos con eso.</p><p>{{despedida}}</p>','accompaniment','care'),
('social','Acompañamiento · Fin de la prueba · Instagram',NULL,'<p>{{saludo}} {{presentacion}}</p><p>La prueba de 30 días de {{name}} en Hospeda está por terminar.</p><p>Para que la ficha siga visible hay que elegir un plan desde la cuenta. Si hace falta, ayudamos con eso.</p><p>{{despedida}}</p>','accompaniment','care'),
('email','Coordinación · Pedido de material · Email','Material para la ficha de {{name}}','<p>{{saludo}}</p><p>{{presentacion}}</p><p>Para avanzar con la ficha de {{name}} en Hospeda necesitamos este material:</p><ul><li>Fotos (la principal y algunas más)</li><li>Una descripción breve</li><li>Horarios y datos de contacto</li><li>Redes o sitio web, si los hay</li></ul><p>Se puede enviar respondiendo este correo o por WhatsApp al {{telefono_hospeda}}.</p><p>{{despedida}}</p>',NULL,'operations'),
('whatsapp','Coordinación · Pedido de material · WhatsApp',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Para avanzar con la ficha de {{name}} necesitamos:</p><p>• Fotos (la principal y algunas más)<br>• Una descripción breve<br>• Horarios y datos de contacto<br>• Redes o sitio web, si los hay</p><p>Se puede enviar por acá.</p><p>{{despedida}}</p>',NULL,'operations'),
('social','Coordinación · Pedido de material · Instagram',NULL,'<p>{{saludo}} {{presentacion}}</p><p>Para avanzar con la ficha de {{name}} necesitamos:</p><p>• Fotos (la principal y algunas más)<br>• Una descripción breve<br>• Horarios y datos de contacto<br>• Redes o sitio web, si los hay</p><p>Se puede enviar por acá.</p><p>{{despedida}}</p>',NULL,'operations'),
('email','Coordinación · Revisión de la ficha · Email','Revisión de la ficha de {{name}}','<p>{{saludo}}</p><p>{{presentacion}}</p><p>La ficha de {{name}} ya está armada{{#if hospeda_url}}: {{hospeda_url}}{{/if}}.</p><p>Antes de publicarla conviene revisar que los datos y las fotos estén bien.</p><p>Cualquier cambio, lo corregimos enseguida.</p><p>{{despedida}}</p>',NULL,'operations'),
('whatsapp','Coordinación · Revisión de la ficha · WhatsApp',NULL,'<p>{{saludo}} {{presentacion}}</p><p>La ficha de {{name}} ya está armada{{#if hospeda_url}}: {{hospeda_url}}{{/if}}.</p><p>Antes de publicarla conviene darle una mirada. Cualquier cambio, lo corregimos.</p><p>{{despedida}}</p>',NULL,'operations'),
('social','Coordinación · Revisión de la ficha · Instagram',NULL,'<p>{{saludo}} {{presentacion}}</p><p>La ficha de {{name}} ya está armada{{#if hospeda_url}}: {{hospeda_url}}{{/if}}.</p><p>Antes de publicarla conviene darle una mirada. Cualquier cambio, lo corregimos.</p><p>{{despedida}}</p>',NULL,'operations');
